INSERT INTO club_category (id, cate_name, logo, description) VALUES
  (1, 'STEM & Innovation', NULL, 'Engineering, robotics, science, and technology-focused clubs.'),
  (2, 'Service & Leadership', NULL, 'Clubs centered on volunteering, civic engagement, and leadership.'),
  (3, 'Creative Arts & Media', NULL, 'Visual arts, performing arts, and multimedia storytelling clubs.'),
  (4, 'Culture & Identity', NULL, 'Clubs organized around heritage, culture, language, and identity communities.'),
  (5, 'Wellness & Athletics', NULL, 'Athletics, physical wellness, recreation, and mental health clubs.'),
  (6, 'Competition & Strategy', NULL, 'Debate, games, olympiads, and strategy-focused clubs.');
INSERT INTO clubs (id, name, slug, alias_name, description, category, meeting_schedule, location, contact_email, advisor, image_url, member_count, achievements) VALUES
  (1, '6th Man', '6th-man', NULL, 'The 6th Man club is a school spirit club dedicated to building spirit and supporting Mountain View athletics. Our members being the student section at spiriting events, organize cheers, and create a fun and especially energetic atmosphere to encourage players and bring them', 'Wellness & Athletics', 'Tuesday · Biweekly · Lunch', 'Room 604', '100030665@mvla.net, 100030922@mvla.net', 'Abigail Stucker', NULL, 0, '[]'),
  (2, 'Aerospace & Aviation', 'aerospace-aviation', NULL, 'The Aerospace & Aviation Club is a group whose members are interested in learning more about military and civil-grade aircraft, rockets, satellites, and more, and the physics and mathematics behind atmospheric and space flight.We will be doing lots of hands-on activities, such as building planes with various materials, water rockets, and detailed scale models. We will also fly RC planes with FPVs, and host building competitions and trivias within the club, where there will be rewards. We will have field trips to related institutes and bases, as well as guest speakers with experience in the aerospace and aviation industries. We serve to provide hands-on activities and practical knowledge to members of the MVHS community, as well as the opportunity to partake in hands-on activities they may not have individual access to.', 'STEM & Innovation', 'Friday · Weekly · Lunch', 'Room 803', '100031386@mvla.net', 'Patrick Murphy', NULL, 0, '[]'),
  (3, 'Analytics Club', 'analytics-club', NULL, 'The Mountain View Analytics Club is a community of analytic enthusiasts passionate about exploring the world of data driven insights. Our club''s primary purpose is to dive into the realm of analytics/statistics, particularly focusing on stock trading analytics and sports analytics. We also plan to engage competitively in the Wharton Global Youth Program, an international data science competition.', 'STEM & Innovation', 'Wednesday · Weekly · Lunch', 'Room 411', '100032204@mvla.net, 100031823@mvla.net', 'Rafael Alapont', NULL, 0, '[]'),
  (4, 'AAH (Animal Assisted Happiness)', 'aah-animal-assisted-happiness', NULL, 'AAH club connects the outside AAH organization with the special education classes and student body at MVHS by bringing our barnyard animals to campus for Spartan''s Pause and vocational visits providing therapeutic services to our students. We further support the AAH farm by completing small projects such as painting birdhouses or making treats for barnyard animals!', 'Wellness & Athletics', 'Tuesday · Biweekly · Lunch', 'Room 708', '100030416@mvla.net', 'Mr. Quillinan', NULL, 0, '[]'),
  (5, 'Animal Welfare Club', 'animal-welfare-club', NULL, 'The Animal Welfare Club hopes to spread awareness about animal-related issues and inspire students to participate in advocacy initiatives through activities, lectures, and projects. Students will have opportunities to research animal welfare problems and learn about how they can contribute to addressing these issues. We can provide mentorship to members who may be interested in designing and implementing their animal welfare projects. We will also organize service activities throughout the year open to everyone.', 'Service & Leadership', 'Friday · Biweekly · Lunch', 'Room A212', '100032549@mvla.net', 'Lindsay Cohen', NULL, 0, '[]'),
  (6, 'Artificial Intelligence Club', 'artificial-intelligence-club', NULL, 'The Artificial Intelligence Club is for students curious about the real-world applications and impact of AI on our daily lives. Members will explore fundamental concepts, including linear regression and machine learning algorithms, alongside other crucial topics like AI ethics. We’ll offer hands-on experience with a variety of AI tools, from prompt engineering with large language models like ChatGPT to experiment with generative AI through Google’s AI experiments. Exciting guest speakers will come to share their cutting-edge perspectives, and our members will help organize events and workshops to help teach the broader community about Artificial Intelligence. Our goal is to empower members with a deep understanding of AI and its practical day-to-day use, fostering the next generation of AI-literate leaders.', 'STEM & Innovation', 'Tuesday · Weekly · Lunch', 'Room 101', '100034197@mvla.net, 100033313@mvla.net', 'Mr. Alapont', NULL, 0, '[]'),
  (7, 'Asian Pacific Union', 'asian-pacific-union', NULL, 'Asian Pacific Union (APU) aims to foster an environment that promotes the understanding of individual Asian American and Pacific Islander Heritage while still simultaneously creating Unity among students of all ethnic backgrounds. We also ensure that Asian Americans Pacific Islanders as a whole have a voice and community here at Mountain View High school. We appeal to everyone who identifies with Asian Pacific culture and those who want to learn more about Asian Pacific culture.', 'Culture & Identity', 'Tuesday · Biweekly · Lunch', 'Room 210', '100030459@mvla.net', 'Nicole Higley', NULL, 0, '[]'),
  (8, 'Badminton Club', 'badminton-club', NULL, 'Badminton Clubs missions is to provide information for the upcoming season and connect newer players with eachother.', 'Wellness & Athletics', 'Tuesday · Monthly · Lunch', 'Room 103', '100030895@mvla.net', 'Annie Liu', NULL, 0, '[]'),
  (9, 'Barkada Club', 'barkada-club', NULL, 'The Barkada Club aims to strengthen the Mountain View High School community by celebrating and sharing the Filipino culture while making new connections amongst other students. Our primary purpose is to serve as a bridge to bring together Filipino students and allies to share Filipino traditions, foods, and values that can help strengthen our heritage. The club serves as both a home away from home for Filipino students and as an educational platform for other students to learn about and appreciate the Filipino culture.', 'Culture & Identity', 'Wednesday · First and last week of the month · Lunch', 'Room 731', '100030229@mvla.net', 'Mangin', NULL, 0, '[]'),
  (10, 'Biology Club', 'biology-club', NULL, 'The biology club is a place for students to come and learn about the field of biology and all the options it has to offer. From academia to industry we bring in people in the field to talk to students about their path to the job and potential ways. Students can follow that path in today’s society. We also host yearly dissections and pay for the Bio Olympiad, which are the main events that many people involved in biology participate in. We also host reviews for AP students taking biology and places to get tutoring in biology topics.', 'STEM & Innovation', 'Monday · Biweekly · Lunch', 'Room 121', '100030599@mvla.net, 100030696@mvla.net', 'Mr. Cmaylo', NULL, 0, '[]'),
  (11, 'Black Student Union', 'black-student-union', NULL, 'The Black Student Union (BSU) is committed to fostering a safe, empowering, and inclusive space for Black students and allies to celebrate culture, build community, and promote academic and social excellence. Through advocacy, education, and engagement, BSU aims to uplift Black voices, honor heritage, and inspire unity and leadership within our school and beyond.', 'Culture & Identity', 'Thursday · Weekly · Lunch', 'Room 720', '100031136@mvla.net', 'David Ortiz', NULL, 0, '[]'),
  (12, 'Bring Change to Mind Club', 'bring-change-to-mind-club', NULL, 'Bring Change to Mind’s High School Program gives teens a platform to share their voices and raise awareness around mental health. Our goal is to empower students to educate one another, and their communities, and to create a culture of peer support within their schools. Together, we’ll fight the stigma around mental illness. All club members get free access to Headspace to practice mindfulness!', 'Wellness & Athletics', 'Tuesday · Biweekly · Lunch', 'Room 117 or 730', '100030575@mvla.net', 'Latina Wharton and Katie Sheldon', NULL, 0, '[]'),
  (13, 'Cancer Awareness and Research Club', 'cancer-awareness-and-research-club', NULL, 'This organization shall have as its objective and purpose to increase knowledge and awareness about the various types of cancer and their profound impacts on our lives. Through a range of activities and workshops, we aim to educate students on important cancer-related topics. Our club will feature presentations and guest speakers who are experts in the field, providing valuable insights and information. Additionally, we will engage in collaborative group projects to research different aspects of cancer, fostering a deeper understanding among our members. To support the fight against cancer, we will organize fundraising events, with all proceeds going to cancer charities and societies.', 'Service & Leadership', 'Tuesday · Weekly · Lunch', 'Room 121', '100030918@mvla.net, 100030631@mvla.net', 'Mr. Cmaylo', NULL, 0, '[]'),
  (14, 'CASC (California Association of Student Councils) Club', 'casc-california-association-of-student-councils-club', NULL, 'The CASC (California Association of Student Councils) Club aims to educate students around leadership and educational policy/legislation. Our club uses leadership curriculum to teach our students about how they can be leaders and how they can positively impact our community. In addition, our club focuses on educational legislation, creating proposals that often become policies for the California State Board of Education or into laws for the California legislative sector. Our parent organization, CASC, hosts different events supporting educational legislation on a local level and on a state level, many of which we will attend.', 'Service & Leadership', 'Monday · Weekly · Lunch', 'Room 111', '100033627@mvla.net, 100033739@mvla.net', 'Jessica Cohen/Matthew Shih', NULL, 0, '[]'),
  (15, 'Chemistry Club', 'chemistry-club', NULL, 'The Chemistry Club is a group whose members seek a passion in the study of Chemistry, be it in any field (As we plan to go over all sorts), feel like the school’s chemistry classes don’t provide enough depth or interactivity/learning in labs, or are interested in opportunities regarding Chemistry or other related fields that the club will provide, such as guest speakers, projects, and prep for competitions such as Chemistry Olympiad, or internships. We will frequently do interactive activities such as lab demos, so the learning can be applied in an applicable and fun way, something we believe the school should provide more of, with our club as an excellent medium for those interested.', 'STEM & Innovation', 'Tuesday · Weekly · Lunch', 'Room 109', '100030760@mvla.net', 'Mrs. Nock', NULL, 0, '[]'),
  (16, 'Chess Club', 'chess-club', NULL, 'The MVHS Chess Club is dedicated to helping members of the community with varying levels of skill and interest in chess to improve at the game while having fun playing. Chess Club includes teaching lessons to beginners, setting up online/local tournaments, and having in-person boards that members can use. Members can come to the chess club during lunch to play and talk with people who share a common interest in the game.', 'Competition & Strategy', 'Monday · Weekly · Lunch', 'Room 725', '100032003@mvla.net', 'Nathan Bowen', NULL, 0, '[]'),
  (17, 'Children''s Health Advocacy', 'children-s-health-advocacy', NULL, 'Our club’s purpose is to provide comfort and joy to hospitalized children with illnesses. We will create happiness boxes that are for children who are currently in the hospital. These could include seasonal items (like holiday-themed crafts), homemade/club made bracelets, favorite character toys, art supplies, and personalized notes to bring comfort and cheer. We will also volunteer to lead or assist with in-hospital activities like arts and crafts, or game nights designed to distract and entertain children during their hospital stay. Spreading awareness throughout our school and helping our school community understand the importance of empathy and support for children with chronic illnesses is also a major goal of ours.', 'Service & Leadership', 'Tuesday · Biweekly · Lunch', 'Room P8', '100030531@mvla.net, 100031589@mvla.net', 'Mr. Sun', NULL, 0, '[]'),
  (18, 'Chinese Culture Club', 'chinese-culture-club', NULL, 'Mountain View High School''s Chinese Culture Club aims to teach Chinese culture and promote diversity on school grounds. In addition, we plan to create a fun, amiable environment for members to have a good time together while engaging in a variety of Chinese activities such as playing Chinese games, singing Chinese songs, and watching Chinese movies.', 'Culture & Identity', 'Tuesday · Biweekly · Lunch', 'Room 602', '100030920@mvla.net', 'Wei Lu', NULL, 0, '[]'),
  (19, 'Computer Science Club', 'computer-science-club', NULL, 'The Computer Science Club aims to provide a space for students of all coding backgrounds to explore computer science. We offer engaging, student-led lessons, collaborative projects, and community events to help members develop programming skills. Our goal is to provide a space for students interested in tech to learn together and engage with like-minded peers in programming projects that address a need or concern in the community.', 'STEM & Innovation', 'Thursday · Weekly · Lunch', 'Room 806', '100030743@mvla.net', 'Ly Nguyen', NULL, 0, '[]'),
  (20, 'Connected Through Cultures', 'connected-through-cultures', NULL, 'The purpose of Connected Through Cultures is to raise awareness about diverse cultures and provide a space for students whose cultural identities are not encompassed by already-existing student unions, filling a vital gap in our school community. We aim to foster an inclusive environment for students from diverse cultural backgrounds, particularly those without dedicated representation, to come together and share their unique traditions, stories, and perspectives. Our club is open to everyone, offering a variety of multicultural activities such as folk dances, educational lectures, and traditional games, with the overall goal of promoting a sense of unity that extends past connections between people of the same culture.', 'Culture & Identity', 'Thursday · Biweekly · Lunch', 'Room 729', '100030798@mvla.net', 'Julie Yick', NULL, 0, '[]'),
  (21, 'Crochet Club', 'crochet-club', NULL, 'The Crochet Club is a welcoming community where all those interested in crocheting can come and learn (including beginners)! We will provide free yarn, hooks, darning needles, and other related materials so all club members can learn at no expense to themselves. The Crochet Club will facilitate donation events to allow students who are interested in giving back to the community to do so (e.g. warm items such as beanies and scarves) and will also host semesterly volunteer events with local organizations to work with and bring a fun experience to residents. We will also teach specific fun projects to increase our club members’ interest in crocheting (e.g. flowers, bookmarks, and amigurumi).', 'Creative Arts & Media', 'Thursday · Biweekly · Lunch', 'Room 109', '100030741@mvla.net', 'Lori Nock', NULL, 0, '[]'),
  (22, 'Dance-a-Gram', 'dance-a-gram', NULL, 'Dance-a-Gram aims to spread joy and form a deeper connection with the senior community through coordinated dance performances. For seniors, watching dance can be a great way to relax, to bring back memories, and to spark conversation. The dance performances we conduct can brighten up their day and can even expose them to art forms and cultures that they’ve never interacted with before.', 'Creative Arts & Media', 'Thursday · Weekly · Lunch', 'Room 607', '100033205@mvla.net', 'Lauren Camarillo', NULL, 0, '[]'),
  (23, 'DERM (Dermatology Educational Research Mission) Club', 'derm-dermatology-educational-research-mission-club', NULL, 'The Dermatology Education Research Mission (DERM) club seeks to educate Mountain View High School students about the integumentary system, raise awareness of skin health, and inspire curiosity in dermatology through education, hands-on activities, and community engagement.', 'STEM & Innovation', 'Thursday · Biweekly · Lunch', 'Room 117', '100031861@mvla.net', 'Jenna Adams', NULL, 0, '[]'),
  (24, 'Drama Llamas', 'drama-llamas', NULL, 'Drama Llamas is an entirely student-run club that puts on a full-scale musical at the end of each school year. The show is directed, teched, choreographed, managed, produced, performed, and sometimes even written by students of Mountain View High School. We were founded with the intent of making all aspects of theatre available to everyone, regardless of past experience. We are committed to creating student-run theater and learning leadership skills.', 'Creative Arts & Media', 'Weekly · After School', 'Room 125', '100031107@mvla.net', 'Anthony Gallego', NULL, 0, '[]'),
  (25, 'Dream Volunteers', 'dream-volunteers', NULL, 'The dream volunteers club is a club for people who want a way to give back to their community. It is based on the organization Dream Volunteers, who organize service trips to other countries. Our member do not have to go on any trips, but they will learn about and particiapte in outside of school volunteer oppurtunies dicsovered by us.', 'Service & Leadership', 'Monday · Biweekly · Lunch', 'Room 604', '100033849@mvla.net', 'Ms. Stucker', NULL, 0, '[]'),
  (26, 'MVHS Drivers Association', 'mvhs-drivers-association', NULL, 'The MVHS Driver’s Association seeks to eradicate the confusion around the process of acquiring a drivers license that prevents many from doing so. By spreading information and resources on how to get a drivers license, we provide students with opportunities to learn where, how, and when to get one. We also teach car maintenance skills and basics, and help students prepare for their permit and license tests. We are open to all, regardless of driving experience, who want to learn, teach, or just have fun.', 'Service & Leadership', 'Wednesday · Biweekly · Lunch', 'Room 115', '100031957@mvla.net', 'Simon Huynh', NULL, 0, '[]'),
  (27, 'Dungeons and Dragons', 'dungeons-and-dragons', NULL, 'The Dungeons & Dragons club aims to help students at MVHS explore and grow in the D&D community', 'Competition & Strategy', 'Tuesday · Biweekly · Lunch', 'Room 512', '100030384@mvla.net', 'Mr. Mercado', NULL, 0, '[]'),
  (28, 'Economics Club', 'economics-club', NULL, 'The Economics Club is a community of students curious about how societies allocate resources and make choices. We emphasize the broader study of economic systems, policies, and theories (from supply and demand to global trade). Through case studies, and debates on current events, members can learn to think critically about how economic forces shape the world. Our goal is to build a foundation in both microeconomics and macroeconomics while connecting theory to real-world issues. In addition, we participate in the National Economics Challenge, where students apply their knowledge of core principles and analytical reasoning in a competitive setting.', 'Service & Leadership', 'Friday · Biweekly · Lunch', 'Room 609', '100032162@mvla.net', 'Rachael Roach', NULL, 0, '[]'),
  (29, 'Esports Club', 'esports-club', NULL, 'The purpose of Mountain View Esports is to promote the growth of esports at Mountain View School by providing students with opportunities to engage in competitive gaming, develop skills in teamwork and strategy, and participate in local and national esports competitions. The club also aims to foster a positive gaming culture and build a supportive community among students', 'Competition & Strategy', 'Friday · Biweekly · Lunch', 'Room 115', '100030745@mvla.net', 'Mr Simon', NULL, 0, '[]'),
  (30, 'F=ma Club', 'f-ma-club', NULL, 'The F=ma club is a group whose members are focused on studying for the F=ma exam, which is taken in February, in hopes of qualifying for USAPhO. Our members work together during meetings to learn new concepts and solve problems together to improve their test-taking and problem solving skills.', 'Competition & Strategy', 'Tuesday · Weekly · Lunch', 'Room 617', '100030715@mvla.net', 'Mr. West', NULL, 0, '[]'),
  (31, 'Fellowship of Christian Athletes', 'fellowship-of-christian-athletes', NULL, 'The vision of FCA is to see the world transformed by Jesus Christ through the influence of coaches and athletes.', 'Service & Leadership', 'Tuesday · Monthly · Lunch', 'Room P6', '100030417@mvla.net', 'Tim Lugo', NULL, 0, '[]'),
  (32, 'Fentanyl & Substance Awareness Club', 'fentanyl-substance-awareness-club', NULL, 'The Fentanyl & Substance Awareness Club has a long term goal of helping to protect MVHS students and our broader community from drug overdoses, particularly those relating to fentanyl. During our bi-weekly meetings, we hope to gather passionate student leaders and work together to improve our personal understanding of the fentanyl crisis and pre-existing policies that work to address it. From there, we hope to share our knowledge with other MVHS students as well as local middle schoolers.', 'Service & Leadership', 'Monday · Biweekly · Lunch', 'Room 116', '100030863@mvla.net, 100032144@mvla.net', 'Mr. Panos', NULL, 0, '[]'),
  (33, 'Film Club', 'film-club', NULL, 'The Film Club welcomes both film enthusiasts and newcomers into engaging discussions regarding all genres of film! Every week, we recommend films to each other and pick movies to watch as a club, which we later review and discuss together. Our goal is to not only discuss what parts of the film we liked, but also take note of the artistic and mechanical aspects of the film. Making the art of cinema and filmmaking available to everyone on campus. Club members also have the opportunity to share their interests through optional film presentations. If you have a favorite film you can’t stop watching, Film Club is the perfect opportunity to share that passion.', 'Creative Arts & Media', 'Friday · Weekly · Lunch', 'Room 103', '100030312@mvla.net', 'Ms. Liu', NULL, 0, '[]'),
  (34, 'Foreign Linguistics Club', 'foreign-linguistics-club', NULL, 'The Linguistics Club aims to create a space where students can explore the scientific study of language in an engaging and accessible way. Through presentations, activities, and outreach, we encourage curiosity about how language works, its role in society, and its connection to culture and identity. Our mission is to make linguistics approachable and relevant to students of all backgrounds and interests.', 'Service & Leadership', 'Monday · Weekly · Lunch', 'Room P3', '100030716@mvla.net', 'Ms. Wu', NULL, 0, '[]'),
  (35, 'French Club', 'french-club', NULL, 'The mission of the French Club is to celebrate the uniqueness and beauty of French culture and traditions and spread it to our surrounding community, in a way that is accommodating of all. This is done through the celebration of French holidays, the honoring of French art, and the playing of French games.', 'Service & Leadership', 'Friday · Biweekly', 'Room 603', 'maggie.h.zhang@gmail.com', 'Clotilde Grès', NULL, 0, '[]'),
  (36, 'French Honors Society', 'french-honors-society', NULL, 'The French Honors Society (SHF) is a group whose members are devoted to studying the French Language and Culture. Members, all of whom participate in French 3H or above, are strong students who are interested in learning more about the culture and developing speaking skills through group activities.', 'Service & Leadership', 'Friday · Biweekly · Lunch', 'Room 603', '100030670@mvla.net', 'Clotilde Gres', NULL, 0, '[]'),
  (37, 'Future Founders', 'future-founders', NULL, 'The goal of Future Founders is to provide MVHS students with the opportunity to learn about entrepreneurship and startup development. We aim to equip members with essential knowledge they will utilize in their futures to launch and build successful businesses. Through our affiliation with the startup ShadowNurse, our participation in local pitching events, and our lectures with adults accomplished in this area, we also strive to help students make meaningful connections and gain real-world experience. Students will have the opportunity to contribute to an established startup: ShadowNurse, in order to gain a sense of the work that needs to be done in order to run a successful business.', 'Service & Leadership', 'Tuesday · Weekly · Lunch', 'Room 501', '100032150@mvla.net', 'Ms. Gilmore', NULL, 0, '[]'),
  (38, 'Gender Sexuality Alliance', 'gender-sexuality-alliance', NULL, 'The Gender-Sexuality Alliance Club is a group seeking to develop a safe space on campus, from those questioning their sexuality or gender to openly out students looking to find like minds to ensure their identities are respected. By encouraging LGBTQ+ students to form powerful group connections and hosting awareness events around campus, such as organizing conferences on how to handle coming out or through a gender-affirming clothes drive, we hope to lessen the disproportionate mental-health burden queer students face.', 'Service & Leadership', 'Friday · Weekly · Lunch', 'Room 726', '100030774@mvla.net', 'Felitia Hancock', NULL, 0, '[]'),
  (39, 'Girls Who Code Club', 'girls-who-code-club', NULL, 'The Girls Who Code Club works to foster an environment in which women in technology at MVHS feel welcome and comfortable to develop their coding skills and to teach members of the community more about computer science through lessons in coding and attending fun events like hackathons. We work towards small-scale individual projects and group projects where club members develop their own websites and teach code at local middle schools.', 'Service & Leadership', 'Monday · Weekly · Lunch', 'Room 801', '100030691@mvla.net', 'Mrs. Winawer', NULL, 0, '[]'),
  (40, 'Guitar Culture Club', 'guitar-culture-club', NULL, 'The Guitar Culture Club (GCC) unites musicians and music lovers to explore the art, history, and culture of the guitar. We serve the Mountain View community by hosting performances, sharing musical knowledge, and creating inclusive spaces where people of all skill levels can connect, learn, and celebrate music together.', 'Service & Leadership', 'Friday · Weekly · Lunch', 'Room 121', '100030857@mvla.net', 'David Cmaylo', NULL, 0, '[]'),
  (41, 'Ignition Club', 'ignition-club', NULL, 'Our mission is to provide technology education accessible to all levels of students and inform them of the transformations in technology in our modern world.', 'Service & Leadership', 'Wednesday · Biweekly · Lunch', 'Room 123', '100030858@mvla.net, 100030761@mvla.net', 'Ann Nguyen', NULL, 0, '[]'),
  (42, 'INARA', 'inara', NULL, 'The INARA Club fundraises for INARA, an organization that provides medical aid to refugee children in war torn countries. Students participate in fundraisers and activities, host interviews with field professionals, and learn about INARA case studies and current humanitarian, political, socioeconomic, and health related issues in the Middle East. Members can expect to hone skills like networking, entrepreneurship, and activism.', 'Service & Leadership', 'Wednesday · Biweekly · Lunch', 'Room 729', '100030812@mvla.net, 100030777@mvla.net', 'Julie Yick', NULL, 0, '[]'),
  (43, 'Information Security Club', 'information-security-club', NULL, 'The Information Security Club is dedicated to educating students about various aspects of offensive and defensive information security. To give back to the community, some community projects that the club participates in include contributing code to make free and open source software, and contributing writeups/tutorials online to assist beginning information security students.', 'STEM & Innovation', 'Tuesday · Weekly · Lunch', 'Room 513', '100032056@mvla.net, 100031313@mvla.net', 'Ms. Chiu', NULL, 0, '[]'),
  (44, 'Japanese Culture Club', 'japanese-culture-club', NULL, 'Japanese Culture Club is a group whose members are interested in a more in-depth study of Japanese culture, including music, Anime, video games, Cosplay, Food, Origami, Ping-pong, and so on. Japan Club is where students learn or share Japanese cultural activities.', 'Service & Leadership', 'Thursday · Weekly · Lunch', 'Room 601', '100030227@mvla.net', 'Minako Walther', NULL, 0, '[]'),
  (45, 'Japanese National Honor Society', 'japanese-national-honor-society', NULL, 'This organization shall have as its objective and purpose to spread Japanese History and Tradition at MVHS through Japanese-related presentations and traditional activities. Any student enrolled in Mountain View High School who has completed or enrolled in 2 years of Japanese Courses, maintaining a 3.5 GPA while also maintaining an overall 3.0 GPA in all MVHS courses, shall be eligible members of the Japanese National Honor Society.', 'Service & Leadership', 'Wednesday · Monthly · Lunch', 'Room 601', '100030227@mvla.net', 'Minako Walther', NULL, 0, '[]'),
  (46, 'Jewish Student Union (JSU)', 'jewish-student-union-jsu', NULL, 'The Jewish Student Union is a group whose members are interested in interacting and building a relationship and community with other Jewish students. We will do this through learning about the history and traditions of Israel, celebrating Jewish holidays, and participating in various events within the greater Bay Area Jewish community.', NULL, 'Wednesday · Biweekly · Lunch', 'Room 728', '100030467@mvla.net', 'Mr. Heiken', NULL, 0, '[]'),
  (47, 'Juggling Club', 'juggling-club', NULL, 'The purpose of the juggling club is to develop, improve, and enhance our juggling skills. By doing this, we develop certain life skills such as resilience and hard work, and are less likely to give up on life’s challenges. We strive to spread the joy and excitement of juggling, while also refining our hand-eye coordination and getting a bit of exercise.', NULL, 'Thursday · Weekly · Lunch', 'Room P1', '100034408@mvla.net', 'Noelle Mendoza', NULL, 0, '[]'),
  (48, 'K-Pop Dance Club', 'k-pop-dance-club', NULL, 'The K-Pop Dance Club strives to bring students together through a shared love of K-pop, while providing opportunities to learn choreography, improve dance skills, and enjoy the experience of dancing in a fun and supportive environment.', NULL, 'Thursday · Weekly · Lunch', 'Room 517', '100031116@mvla.net', 'Lauren Kato', NULL, 0, '[]'),
  (49, 'Korean Culture Club', 'korean-culture-club', NULL, 'Korean Culture Club is a place where students can express and explore their interest in Korean culture/language and Korean history. Our members will seek to understand in depth of the culture and spread awareness and positivity of the culture with the MVHS community through participating in campus community events and club meetings.', NULL, 'Thursday · Biweekly · Lunch', 'Room 508', '100034215@mvla.net', 'Julie Song', NULL, 0, '[]'),
  (50, 'Latino Student Union', 'latino-student-union', NULL, 'Focusing on promoting culture awareness and community among Latino students.', NULL, 'Wednesday · Biweekly · Lunch', 'Room 112', '100031972@mvla.net', 'David Marroquin', NULL, 0, '[]'),
  (51, 'Leo Club', 'leo-club', NULL, 'The Leo Club is a philanthropy/community service club where our members who enjoy volunteering can give back to their community by joining and participating in our club events. Students part of the Leo Club will have the opportunity to plan and interact in fun, diverse, and inclusive community service projects such as trash pick-up, beach cleaning, senior tech events, bicycle repair, and more. We are also part of a parent organization, called the Lions Club, which is a non-profit organization dedicated to giving back through community service.', NULL, 'Tuesday · Biweekly · Lunch', 'Room 729 or 609', '100032686@mvla.net', 'Dr. Yick and Ms. Roach', NULL, 0, '[]'),
  (52, 'M1820 Christian Club', 'm1820-christian-club', NULL, 'M1820 exists to encourage Christians to boldly live out their faith on school grounds. It is our mission to disciple believers and equip them with the wisdom and passion that is necessary for them to then go out and spread the values of faith, hope, and charity to the greater community, starting here at MVHS. We hope to attain these goals by teaching about the core values and principles of Christianity, participating in community service projects, and engaging in Biblical discussions to build our faith and share the hope that we have in the gospel of Jesus Christ.', NULL, 'Friday · Biweekly · Lunch', 'Room 125', '100030417@mvla.net', 'Anthony Gallego', NULL, 0, '[]'),
  (53, 'Magic the Gathering Club', 'magic-the-gathering-club', NULL, 'The Magic the Gathering Club is a recreational club where people can hang out with friends and have a good time playing one of the most popular card games of all time: Magic the Gathering. Our community event is teaching middle schoolers how to play Magic the Gathering.', NULL, 'Friday · Biweekly · After School', 'Room 428', '100030671@mvla.net', 'Kevin Heiken', NULL, 0, '[]'),
  (54, 'Marine Biology and Ocean Club', 'marine-biology-and-ocean-club', NULL, 'The Marine Biology and Ocean Club is a group whose members will learn about diverse marine ecosystems and ocean health through informative presentations and interactive activities. We will host guest speakers, offer volunteer opportunities, dissections, beach cleanups, and field trips to help members better understand marine biology, how climate change has impacted marine ecosystems, and how we can become more active in restoring our oceans.', NULL, 'Thursday · Biweekly · Lunch', 'Room 111', '100030696@mvla.net', 'Jessica Cohen', NULL, 0, '[]'),
  (55, 'Math Club', 'math-club', NULL, 'The Math Club focuses on competitive and proof-based math outside of the school framework. We prepare students to succeed in math competitions. Members of the club can also help teach competition math to students at Blach and Graham.', NULL, 'Wednesday · Weekly · Lunch', 'Room 409', '100031166@mvla.net, 100032003@mvla.net', 'Annie Liu', NULL, 0, '[]'),
  (56, 'MEChA', 'mecha', NULL, 'Our mission as M.E.Ch.A is to foster positive change and revive our old club''s history within the community by standing up for educational policy changes that encourage equitable representation and amplify Latinx voices in our educational community; addressing the challenges Latinx and other groups face in educational and communal aspects. We are dedicated to creating a more inclusive and just society where students of all kinds of backgrounds are recognized and provided with the opportunities and resources they have long deserved.', NULL, 'Monday · Biweekly · Lunch', 'Room 120', '100030594@mvla.net', 'Yoli Gavaldon', NULL, 0, '[]'),
  (57, 'MeToo', 'metoo', NULL, 'The Me Too Club works to spread awareness about sexual assault and harassment. We create a safe space for survivors to feel supported and share their stories. Our mission is to educate others about consent, healthy relationships, and respect, while working together to end sexual violence.', NULL, 'Tuesday · Biweekly · Lunch', 'Room A202', '100030402@mvla.net, 100031394@mvla.net', 'Lindsay Cohen', NULL, 0, '[]'),
  (58, 'Mock Trial', 'mock-trial', NULL, 'The Mock Trial Club aims to deliver an early exposure to the process of law and litigation through discussion of the law and its procedures as well as a year-long simulation of a trial that students participate in. They will compete against other schools and will be graded on performance and understanding of due process. Taught by attorney lawyers from Santa Clara’s Public Defender’s Office, students will have first-hand insight into how the system works and how to navigate its intense network of procedure.', NULL, 'Tuesday · Weekly · After School', 'Room 731', '100031144@mvla.net', 'Latina Wharton', NULL, 0, '[]'),
  (59, 'Model UN', 'model-un', NULL, 'This organization shall have as its objective and purpose to serve the students of Mountain View and provide them with a stronger understanding of the United Nations. These shall include: Attending MUN conferences Learning about diplomacy Promoting real life civic engagement', NULL, 'Thursdays · Weekly · Lunch', 'Room 505', '100034069@mvla.net', 'Ms. Medina', NULL, 0, '[]'),
  (60, 'Mountain View Los Altos Speech & Debate', 'mountain-view-los-altos-speech-debate', NULL, 'At MVLASD, we believe Speech and Debate (also known as “forensics”) is one of the most valuable activities a student can participate in. Participants develop research skills, strategies that will help them on standardized tests, and the ability to speak in front of large groups with poise and confidence. Students also see dramatic improvements in writing organization, clarity and concision of speech and prose, and the ability to think quickly, critically, and from multiple perspectives. Students learn to set goals, delineate the steps needed to achieve them, and then hit the ground running! Students make lifelong friends in speech and debate! High school is a critical period for developing social connections, and forensics students often say speech and debate feels like a second home to them. Please check out our website: mvlasd.club for more information.', NULL, 'Monday, Wednesday · Weekly · After School', 'Library, and zoom', '100030546@mvla.net', 'Julie Herman', NULL, 0, '[]'),
  (61, 'Mountain View Science Olympiad', 'mountain-view-science-olympiad', NULL, 'The MVHS Science Olympiad club educates and inspires students in all STEM (science, technology, engineering, and math) disciplines through hands-on activities. The club includes team members that compete at various Science Olympiad competitions, and also provides learning opportunities to explore science further. During workshop meetings we do lab activities, have subject expert lectures, and prepare for upcoming competitions.', NULL, 'Friday · Weekly · after school', 'Room 617', '100031166@mvla.net, 100030741@mvla.net', 'Jack West, Anthony Gallego', NULL, 0, '[]'),
  (62, 'Music Outreach Club', 'music-outreach-club', NULL, 'The MVHS Music Outreach Club seeks to entertain people at senior homes, assisted living facilities, and hospitals. We also hope to create a low stress performance environment where members can practice their musical talents such as instruments, singing, and dancing. We offer several performance opportunities each quarter and have meetings every month.', NULL, 'Tuesday · Monthly · Lunch', 'Packard Hall', '100031309@mvla.net', 'Mr. Alegria', NULL, 0, '[]'),
  (63, 'Muslim Student Association', 'muslim-student-association', NULL, 'The Muslim Students'' Association (MSA) strives to build unity through diversity and education. We aim to provide programs for people of all backgrounds to learn and meet with other Muslims and friends. The purpose of the MSA is to create a welcoming and inclusive space for Muslim students at Mountain View High School, to foster a sense of community, understanding, and cultural awareness among its members, and to engage in educational, social, and service-oriented activities that promote the values of Islam.', NULL, 'Tuesday, Friday · Friday meetings are weekly. Tuesday meetings are biweekly. · Lunch', 'Room 720', '100032608@mvla.net', 'David Ortiz', NULL, 0, '[]'),
  (64, 'MV Greenteam', 'mv-greenteam', NULL, 'The Mountain View Green Team''s goal on campus is to spread awareness around the environment. We are aiming to push our school and community collectively and individuals personally to better the choices they make towards the environment. We also work to increase sustainability on campus through semester projects that were complete (ex: composting, recycling, gardening, waste reduction, anti idling and auditing).', NULL, 'Tuesday · Weekly · Lunch', 'Room 117', '100030249@mvla.net', 'Ms. Adams and Mr. Figueroa', NULL, 0, '[]'),
  (65, 'MVHS Drivers Association', 'mvhs-drivers-association-2', NULL, 'The MVHS Driver’s Association seeks to eradicate the confusion around the process of acquiring a drivers license that prevents many from doing so. By spreading information and resources on how to get a drivers license, we provide students with opportunities to learn where, how, and when to get one. We also teach car maintenance skills and basics, and help students prepare for their permit and license tests. We are open to all, regardless of driving experience, who want to learn, teach, or just have fun.', NULL, 'Wednesday · Biweekly · Lunch', 'Room 113', '100031957@mvla.net', 'Simon Huynh', NULL, 0, '[]'),
  (66, 'MVHS Jazz and Composition Club', 'mvhs-jazz-and-composition-club', NULL, 'This organization shall have as its mission to teach students about jazz music, its history, and to provide them with a space to play it.', NULL, 'Wednesday · Biweekly · Lunch, Afterschool', 'Packard Hall', '100032063@mvla.net', 'Ricky Alegria', NULL, 0, '[]'),
  (67, 'MVHS Makers With A Mission', 'mvhs-makers-with-a-mission', NULL, 'Our club is a creative, community-driven space where art, engineering, and compassion come together to make a meaningful impact. We design and build 3D projects using materials like clay, cardboard, fabric, and 3D-printed parts—creating personalized items that benefit the community and fun take-home projects. We also provide volunteer opportunities for MVHS students to teach STEAM to young unhoused kids at local shelters, using creativity to spark learning and joy. Open to all skill levels, our inclusive makers club welcomes artists, engineers, and anyone eager to connect and create.', NULL, 'Tuesday · Biweekly · Lunch', 'Room 721', '100032293@mvla.net', 'Cardenas', NULL, 0, '[]'),
  (68, 'MVHS Pokémon Club', 'mvhs-pokemon-club', NULL, 'We strive to create an environment for all Pokémon fans to celebrate the franchise.', NULL, 'Friday · Biweekly · Lunch', 'Room 601', '100030365@mvla.net', 'Ms. Minako', NULL, 0, '[]'),
  (69, 'MVHS Red Cross Club', 'mvhs-red-cross-club', NULL, 'The MVHS Red Cross Club will work to continue the mission of the Red Cross and work to improve the lives of people in our community and the rest of the world. Members are given the opportunity to help supply people in need of toiletries and blankets, support communities recovering from a disaster and learn about blood health and blood donation. We will also improve our school community by educating about preparedness to help themselves and others in the event of a disaster.', NULL, 'Thursday · Weekly · Lunch', 'Room 110', '100030626@mvla.net', 'Meghan Engle', NULL, 0, '[]'),
  (70, 'MVHS UNICEF', 'mvhs-unicef', NULL, 'The Mountain View UNICEF club aims to raise awareness about global issues affecting children and communities around the world, while supporting UNICEF’s mission through education and fundraising. As a club, we plan to host meetings that focus on important topics such as access to clean water, education, conflict, and more. These meetings will include presentations, discussions, and interactive activities to help students better understand these issues as well as how they can make a difference. We also plan to organize fundraisers throughout the year such as bake sales and donation drives, with proceeds going to support UNICEF’s work. Through these efforts, we hope the Mountain View UNICEF club will be a space where students can learn, take action, and contribute to meaningful global causes.', NULL, 'Thursday · Biweekly · Lunch', 'Room A204', '100032144@mvla.net, 100032220@mvla.net', 'Luz Escalante', NULL, 0, '[]'),
  (71, 'MVHS Women in STEM', 'mvhs-women-in-stem', NULL, 'The Women in STEM club is a club where women are empowered to pursue and explore interests or careers in STEM related fields and jobs. We aim to provide an inclusive and supportive space for learning, mentorship, and community outreach through hands-on activities, STEM events, and guest speakers for the local youth and students of Mountain View. Through the establishment of this club, we hope that more young girls and women are inspired to explore STEM subjects with confidence and challenge the stereotypes that may be holding them back.', NULL, 'Wednesday · Weekly · Lunch', 'Room P4 (Portables 4)', '100034056@mvla.net', 'Ms. Babiak', NULL, 0, '[]'),
  (72, 'National Art Honors Society', 'national-art-honors-society', NULL, 'The National Art Honor Society aims to inspire and recognize students who have shown an outstanding ability in art, foster a spirit of dedication to the pursuit of art, and bring art education to the attention of the school and community.', NULL, 'Wednesday · Biweekly · Lunch', 'Room 110', '100031917@mvla.net', 'Meghan Engle', NULL, 0, '[]'),
  (73, 'Native American Student Union', 'native-american-student-union', NULL, 'The Native American Student Union is a group whose members have a strong desire to enhance the visibility of Native Americans and their culture on campus. Through this Student Union, our members aim to promote a better understanding and appreciation of Native American culture. Additionally, we strive to create a welcoming environment for positive social interactions between the community and the students through fundraising for food/clothing (particularly for Native American communities) and interactive activities, to tackle stereotypes. We are looking forward to supporting the Native American and Mountain View community through fundraising for basic necessities and tackling stereotypes through educating students on the truth of Native American culture and people.', NULL, 'Friday · Biweekly · Lunch', 'Room 705', '100030430@mvla.net', 'Ms. Casem', NULL, 0, '[]'),
  (74, 'Owed Soap Initiative', 'owed-soap-initiative', NULL, 'Our club is a branch of our non-profit organization, Owed Soap, whose goal is to take used cooking oil from restaurants, turn it into soap, and then donate this soap to our community. The goal of our club is to have more people to fundraise, make soap, and generally bring awareness towards our issue. In our club we will organize fundraising, package and prepare our soap for shipping, find new partnerships, and learn about our cause.', NULL, 'Wednesday · Biweekly · Lunch', 'Room 703', '100033252@mvla.net, 100032207@mvla.net', 'Ms Boyle', NULL, 0, '[]'),
  (75, 'Persian Culture Club', 'persian-culture-club', NULL, 'To educate and inform people of all the beautiful aspects of Persian Culture in MVHS through food, music, film, etc.', NULL, 'Wednesday · Once a month · Lunch', 'Room 731', '100031962@mvla.net', 'Brook Mangin', NULL, 0, '[]'),
  (76, 'Personal Finance Club', 'personal-finance-club', NULL, 'The MVHS Personal Finance Club focuses on expanding high school students’ financial literacy in order to help them be more financially independent as they become adults. It also provides a community where students can clarify questions about financial matters such as taxes or investing. In the future, our club hopes to continue to participate in volunteering events at the local library in order to increase access to financial education, such as money management, for youth.', NULL, 'Thursday · Biweekly · Lunch', 'Room 604', '100030691@mvla.net', 'Señora Stucker', NULL, 0, '[]'),
  (77, 'Physics and Astronomy Club', 'physics-and-astronomy-club', NULL, 'The Physics and Astronomy Club serves to spread the excitement of both the theoretical and applicational parts of physics, astronomy, and astrophysics to members of all experience levels. We will conduct fun labs and build devices using principles of physics, such as rockets, particle accelerators, and matchbox microphones. We will dive into aspects of physics and astronomy, including black holes and dark matter, to elevate member''s interest in the stunning field. Guest speakers from prestigious universities will further elevate members'' understanding of concepts and applications of physics and astronomy. Additionally, we will watch and understand the concepts behind popular physics and astronomy movies.', NULL, 'Monday · Once a week, 3 weeks per month · Lunch', 'Room 618', '100032668@mvla.net', 'Gina Dunsmore', NULL, 0, '[]'),
  (78, 'Pitch & Prototype', 'pitch-prototype', NULL, 'The Pitch & Prototype Club is a community for students interested in innovation, problem solving, and public speaking. Our members practice turning ideas into simple prototypes and present them through pitch style events and meetings. We serve the MVHS community by providing students a space to pursue their passions and turn their ideas to a reality.', NULL, 'Tuesday · Biweekly · Lunch', 'Room 703', '100034291@mvla.net', 'Ms.Boyle', NULL, 0, '[]'),
  (79, 'Poetry Club', 'poetry-club', NULL, 'Our poetry club exists to inspire creative expression, foster a supportive and safe community of writers, and celebrate the power of words. We provide a safe space for poets of all backgrounds and experience levels to share their voices, explore new forms, and grow together through workshops, open mics, and collaborative projects.', NULL, 'Tuesday · Biweekly · Lunch', 'Room 302', '100030232@mvla.net', 'Lindsay Cohen', NULL, 0, '[]'),
  (80, 'Psychology Club', 'psychology-club', NULL, 'The MVHS Psychology Club aims to promote appreciation for all disciplines of psychology through engaging lessons, hosting fun activities like student surveys, and cultivating a safe space to talk about mental illnesses. Through weekly meetings, members will have the opportunity to learn about psychology career pathways; the importance of mental health; how psychology affects our thoughts, behavior, and the world around us on a daily basis; and how we can use psychology to improve ourselves. We frequently feature a new psychology concept spotlight article on our website, and plan to host psychologists and interactive speaker events so club members can learn more about the world of psychology. We welcome all students.', NULL, 'Wednesday · Biweekly · Lunch', 'Room 416', '100030805@mvla.net', 'Ms.Higley', NULL, 0, '[]'),
  (81, 'Puzzle Club', 'puzzle-club', NULL, 'The Puzzle Club is a group whose members enjoy solving puzzles such as sudoku, crosswords, escape rooms, logic problems, mystery hunt puzzles, and other fun brain challenges. The club aims to bring together like-minded people to encourage collaborative puzzle solving and foster a puzzling community. We plan on participating as a team in multiple national events, prepare members for individual competitions, and host local events such as escape room trips.', NULL, 'Friday · Biweekly · Lunch', 'Room P2', '100032056@mvla.net', 'Param Singh', NULL, 0, '[]'),
  (82, 'Rock Climbing Club', 'rock-climbing-club', NULL, 'Rock climbing club aims to bring together students (beginner or pro) who are interested in climbing, whether indoors at gyms or learning about outdoor climbing, while focusing on learning new techniques, safety, and building a community at school.', NULL, 'Thursday · Biweekly · Lunch', 'Room 513', '100032304@mvla.net', 'Ms. Chiu', NULL, 0, '[]'),
  (83, 'RL Game Club', 'rl-game-club', NULL, 'The Reinforcement Learning Game Club is dedicated to teaching students how to use reinforcement learning to train ML models that can play games. Through practical projects, friendly competitions, and easily accessible learning opportunities, we hope to promote teamwork, creativity, and problem-solving skills.', NULL, 'Thursday · Weekly · Lunch', 'Room 102', '100032240@mvla.net', 'Ms. Richmond', NULL, 0, '[]'),
  (84, 'SLAM Magazine', 'slam-magazine', NULL, 'SLAM Magazine is an organization and independent student-run publication that is dedicated to illuminating social justice issues in our community that don''t receive mainstream attention. We strive to provide insight and understand the complexities behind systems of oppression based on race, ethnicity, gender, ability, and other identities through the arts. For our team members, our organization provides career-applicable skills and experience in design, photography, media marketing, business, and writing/journalism. Students work with their teams and as an organization to produce two issues annually that get sold and distributed throughout the MVLA community.', NULL, 'Wednesday · Weekly · Afterschool 3:10-4:10pm', 'Room 109', '100030739@mvla.net', 'Lori Nock', NULL, 0, '[]'),
  (85, 'Slavic Student Union', 'slavic-student-union', NULL, 'To provide a safe space and community for Slavic students at MVHS through various Slavic-related activities and events.', NULL, 'Thursday · Biweekly · Lunch', 'Room 104', '100031906@mvla.net, 100032900@mvla.net', 'Ms. Griffin', NULL, 0, '[]'),
  (86, 'South Asian Student Union', 'south-asian-student-union', NULL, 'This organization shall have as its objective and purpose focused on showing light upon racism and other hardships South Asians face in America. This club calls for any high school student interested in learning about the hardships in South Asian culture and bonding with the people who share the same problems.', NULL, 'Thursday · Biweekly · Lunch', 'Room 725', '100030391@mvla.net', 'Nathan Bowen', NULL, 0, '[]'),
  (87, 'Spartan Buddies', 'spartan-buddies', NULL, 'Spartan Buddies at MVHS unites special needs students in our special education and Life Skills program with neurotypical MVHS students in the hopes of creating genuine friendship connections and increasing inclusivity at school. For peers with special needs, feeling different and excluded is an everyday experience. The simple action of pairing students with their Spartan Buddy and encouraging them to have genuine conversations while guiding them with fun activities can be life changing for them. It can develop intense feelings of belonging and overall joy in these students, and that is more important than we as neurotypical individuals may ever understand.', NULL, 'Thursday · Weekly · Lunch', 'Room 708 (Mr.Q''s classroom and 700''s quad, outside)', '100030805@mvla.net', 'Mr.Quillinan (Mr.Q)', NULL, 0, '[]'),
  (88, 'Spartan Equity Partners', 'spartan-equity-partners', NULL, 'Our mission is to inspire and empower students to deepen their understanding of investing by actively preparing for and competing in the Wharton Global Youth Investment Competition. Through research, teamwork, and strategic decision-making, we aim to build a passion for global markets and responsibility from investing.', NULL, 'Friday · Weekly · Lunch', 'Room 510', '100032546@mvla.net', 'Juan Alvarez', NULL, 0, '[]'),
  (89, 'Stationery Club', 'stationery-club', NULL, 'Our mission is to teach others'' how to design successful promotional material and share our love for design with the community.', NULL, 'Friday · Biweekly · Lunch', 'Room 724', '100032036@mvla.net', 'Alisa Burmeister', NULL, 0, '[]'),
  (90, 'STEAM Club', 'steam-club', NULL, 'This organization shall have as its objective and purpose is to inspire children to explore STEM in their future through our interactive projects. These shall include: Summer programs, Spring interactive STEM projects, and Interactive lessons in our club meetings about how to best properly teach younger children.', NULL, 'Wednesday · Biweekly · Lunch', 'Room 720', '100031254@mvla.net, 100030770@mvla.net', 'Mr. Ortiz', NULL, 0, '[]'),
  (91, 'Student Athlete Service Club', 'student-athlete-service-club', NULL, 'The Student Athlete Service Club strives to give back to the community, as the community has given student athletes a lot in terms of support. We will address local issues of pollution and homelessness through various service projects such as food drives and cleaning/beautification projects. We will support underprivileged segments of our community by including young underprivileged kids in sports and tutoring events. Young athletes will be supported through a variety of service events such as sports clinics and equipment drives. Additionally, our club will help promote events for our school sports programs, if possible. Long term, we want the student athlete service club to be a strong presence in promoting school sports and the prosperity of our school/community.', NULL, 'Thursday · Biweekly · Lunch', 'Room 727', '100031831@mvla.net', 'Kirk Jennings', NULL, 0, '[]'),
  (92, 'Taiwanese American Student Association', 'taiwanese-american-student-association', NULL, 'The Taiwanese American Student Association (TASA) aims to build a safe and inclusive environment at Mountain View High School where members are able to share their cultural experiences in Taiwan. This club will educate students on a culture not often talked about. The Taiwanese American Student Association will also benefit each member’s communication and speaking skills. Some topics we will cover include local attractions, different cities, and Taiwanese food.', NULL, 'Friday · Biweekly · Lunch', 'Room 513', '100031152@mvla.net', 'Jennifer Chiu', NULL, 0, '[]'),
  (93, 'Technology Public Policy Club', 'technology-public-policy-club', NULL, 'The Technology Public Policy Club (“The Tech Pub”) is a first-of-its-kind, teen-led think tank and advocacy group where students not only explore how cutting edge tech has real-world impact but they are provided the forum, the support and the skills to learn how to take action. At the Tech Pub, we don’t just help members think about what’s right, we will work together to help advocate and implement what’s right at the structural level. As technology becomes intertwined with governance and political influence shapes drastic changes to governance, the world needs leaders who understand both sides of the equation: how technology works and how to regulate it.', NULL, 'Tuesday · Biweekly · Lunch', 'Room 105', '100030700@mvla.net', 'Mrs. Carranza', NULL, 0, '[]'),
  (94, 'TEDxMVHS', 'tedxmvhs', NULL, 'TEDxMVHS is a student-led club dedicated to inspiring and empowering others through the sharing of "ideas worth spreading." We organize TEDx-style events featuring talks on diverse topics, fostering a culture of innovation and curiosity within our community. Our members are passionate about creating platforms for meaningful discussions and creative thinking. As a community event, we plan to host a TEDxYouth event where local students can present their ideas to the public and engage in interactive workshops.', NULL, 'Tuesday · Biweekly · Lunch', 'Room P11', '100032533@mvla.net', 'Jyoti Reid', NULL, 0, '[]'),
  (95, 'Theatre Club', 'theatre-club', NULL, 'The Theatre Club seeks to connect MVHS students with a love of theater by providing theatre games, events, and educational opportunities that foster engagement with the theater community.', NULL, 'Thursday · Weekly · Lunch', 'Room 413', '100032246@mvla.net', 'Pancho Morris', NULL, 0, '[]'),
  (96, 'The MVHS AIAS Architecture Club', 'the-mvhs-aias-architecture-club', NULL, 'As a chapter (club) of the American Institute of Architecture Students (AIAS), The MVHS AIAS Club aims to foster education and appreciation for architecture among MVHS students. We welcome students who are interested in a potential architecture career or who are simply curious about architecture and would like to explore more about the subject. Our club provides additional resources about architecture as we will invite guest architecture speakers, participate in fun design challenges, and learn more about potential career pathways of architecture. Our community event is raising awareness about World Architecture Day and National Architecture Week.', NULL, 'Thursday · Weekly · Lunch', 'Portable 5', '100031122@mvla.net', 'Jared Darby', NULL, 0, '[]'),
  (97, 'The Pediatrics Club', 'the-pediatrics-club', NULL, 'The Pediatrics Club is a club in which participants will engage in lectures, activities, and labs concerning various areas of Pediatrics. For instance, our club will explore the fields of pediatric cardiology, pediatric neurology, and pediatric surgery. Our club would happily accept donations of synthetic dissection kits, surgical and dissection tools, children''s toys, and silicone human model pads. Our community events consist of “Adopt a teddy bear donation fair”, collecting books and toys for the children''s hospital, painting cups to donate to children''s hospitals, and hosting a children’s introduction to healthcare fair.', NULL, 'Tuesday · Biweekly · Lunch', 'Room 703', '100033684@mvla.net, 100033586@mvla.net', 'Heather Boyle', NULL, 0, '[]'),
  (98, 'The Star Wars Club', 'the-star-wars-club', NULL, 'The Star Wars Club is a group whose members are interested in a thorough analysis of Star Wars, including its ideological relevance, complex themes, diverse characters, lore, music, special effects, and relation to current society. The club represents a positive space for Star Wars fans to deeply discuss questions, comment on Star Wars content, and have some fun together, learning more as they go along. We will also encourage members to draft papers about Star Wars in an academic lens. We also plan on doing Star Wars themed community service projects to benefit younger students in nearby schools, including guided book readings, celebrations, and even movie nights.', NULL, 'Friday · Weekly · Lunch', 'Room 708', '100032151@mvla.net, 100032208@mvla.net', 'Mr. Heiken', NULL, 0, '[]'),
  (99, 'Ukrainian Culture Club', 'ukrainian-culture-club', NULL, 'The Ukrainian Culture Club is a group whose members are interested all aspects of Ukrainian Culture. We hope to share the beauty of Ukrainian food, dance, clothing, history, and artistry. We will also look for opportunities to support humanitarian relief efforts in Ukraine.', NULL, 'Thursday · Biweekly · Lunch', 'Room 721', '100031715@mvla.net, 100032037@mvla.net', 'Ms. Cardenas', NULL, 0, '[]'),
  (100, 'Unhoused Awareness', 'unhoused-awareness', NULL, 'Our club''s purpose is to support and advocate for people experiencing unhoused in our community by participating in drives, making blankets, creating cards for those in foster care, and more.', NULL, 'Friday · Biweekly · Lunch', 'Room 704', '100032253@mvla.net', 'Danie Robledo', NULL, 0, '[]'),
  (101, 'Vietnamese Student Association (VSA)', 'vietnamese-student-association-vsa', NULL, 'The purpose of a Vietnamese Student Association is to foster a strong sense of community and cultural pride among Vietnamese individuals and those interested in Vietnamese culture. It aims to preserve and promote Vietnamese traditions, language, and heritage through various cultural events and educational activities. The club also provides support and resources to its members, helping them connect, network, and navigate challenges, especially for newcomers interested in the culture. Additionally, it serves as a platform to advocate for the interests of the Vietnamese community, while promoting diversity, inclusion, and cultural exchange within the broader society.', NULL, 'Tuesday · Biweekly · Lunch', 'Room 612', '100030766@mvla.net', 'Mr. David Campbell', NULL, 0, '[]'),
  (102, 'Women Athlete''s Club', 'women-athlete-s-club', NULL, 'We will promote connection and both physical and emotional wellness for women athlete''s. We will achieve this by creating a welcome, supportive place for experiences to be shared and educating about nutrition and recovery methods.', NULL, 'Tuesday · Biweekly · Lunch', 'Room P8', '100033123@mvla.net', 'Taran Sun', NULL, 0, '[]'),
  (103, 'Women''s Empowerment Club', 'women-s-empowerment-club', NULL, 'We strive for gender equality at MVHS as well as on a global scale.', NULL, 'Monday · Biweekly · Lunch', 'Room 312', '100030778@mvla.net', 'Ariele Wildwind', NULL, 0, '[]'),
  (104, 'Write for Blue', 'write-for-blue', NULL, 'Write For Blue is a club that aims to increase support for seniors in our community through the value of interaction. By writing letters, creating art, and building care packages, our club will teach students about the value of seniors in their lives. It will also teach students the value of nursing homes, hospice, assisted living, and retirement home organizations. Through these actions, Write for Blue hopes to increase awareness and support for seniors in the Mountain View/Los Altos community.', NULL, 'Tuesday · Biweekly · Lunch', 'Room 609', '100030853@mvla.net', 'Rachael Roach', NULL, 0, '[]'),
  (105, 'Youth Hunger Initiative', 'youth-hunger-initiative', NULL, 'We are a group of students dedicated to help fight hunger in our community. Our members will volunteer at soup kitchens, distribute food to those in need, spread awareness and create fundraisers to raise money. We work with kindness and compassion to provide little steps to fight hunger in our world today.', NULL, 'Monday · Biweekly · Lunch', 'Room 724', '100033343@mvla.net', 'Alisa Burmeister', NULL, 0, '[]'),
  (106, 'Yearbook Club', 'yearbook-club', NULL, 'The MVHS Yearbook club is a group that aims to support the Olympiad staff in producing a quality yearbook by photographing school events, partnering on spreads, and reaching out to other campus clubs and organizations. Members will gain skills in collaboration, photography, and graphic design.', NULL, 'Monday · Biweekly · Lunch', 'Room 514', '100030249@mvla.net', 'Mr. Chang', NULL, 0, '[]');
INSERT INTO club_social_medias (club_id, social_type, link_name, link_url) VALUES
  (1, '6th Man', '6th-man', NULL, 'The 6th Man club is a school spirit club dedicated to building spirit and supporting Mountain View athletics. Our members being the student section at spiriting events, organize cheers, and create a fun and especially energetic atmosphere to encourage players and bring them', 'Wellness & Athletics', 'Tuesday · Biweekly · Lunch', 'Room 604', '100030665@mvla.net, 100030922@mvla.net', 'Abigail Stucker', NULL, 0, '[]'),
  (2, 'Aerospace & Aviation', 'aerospace-aviation', NULL, 'The Aerospace & Aviation Club is a group whose members are interested in learning more about military and civil-grade aircraft, rockets, satellites, and more, and the physics and mathematics behind atmospheric and space flight.We will be doing lots of hands-on activities, such as building planes with various materials, water rockets, and detailed scale models. We will also fly RC planes with FPVs, and host building competitions and trivias within the club, where there will be rewards. We will have field trips to related institutes and bases, as well as guest speakers with experience in the aerospace and aviation industries. We serve to provide hands-on activities and practical knowledge to members of the MVHS community, as well as the opportunity to partake in hands-on activities they may not have individual access to.', 'STEM & Innovation', 'Friday · Weekly · Lunch', 'Room 803', '100031386@mvla.net', 'Patrick Murphy', NULL, 0, '[]'),
  (3, 'Analytics Club', 'analytics-club', NULL, 'The Mountain View Analytics Club is a community of analytic enthusiasts passionate about exploring the world of data driven insights. Our club''s primary purpose is to dive into the realm of analytics/statistics, particularly focusing on stock trading analytics and sports analytics. We also plan to engage competitively in the Wharton Global Youth Program, an international data science competition.', 'STEM & Innovation', 'Wednesday · Weekly · Lunch', 'Room 411', '100032204@mvla.net, 100031823@mvla.net', 'Rafael Alapont', NULL, 0, '[]'),
  (4, 'AAH (Animal Assisted Happiness)', 'aah-animal-assisted-happiness', NULL, 'AAH club connects the outside AAH organization with the special education classes and student body at MVHS by bringing our barnyard animals to campus for Spartan''s Pause and vocational visits providing therapeutic services to our students. We further support the AAH farm by completing small projects such as painting birdhouses or making treats for barnyard animals!', 'Wellness & Athletics', 'Tuesday · Biweekly · Lunch', 'Room 708', '100030416@mvla.net', 'Mr. Quillinan', NULL, 0, '[]'),
  (5, 'Animal Welfare Club', 'animal-welfare-club', NULL, 'The Animal Welfare Club hopes to spread awareness about animal-related issues and inspire students to participate in advocacy initiatives through activities, lectures, and projects. Students will have opportunities to research animal welfare problems and learn about how they can contribute to addressing these issues. We can provide mentorship to members who may be interested in designing and implementing their animal welfare projects. We will also organize service activities throughout the year open to everyone.', 'Service & Leadership', 'Friday · Biweekly · Lunch', 'Room A212', '100032549@mvla.net', 'Lindsay Cohen', NULL, 0, '[]'),
  (6, 'Artificial Intelligence Club', 'artificial-intelligence-club', NULL, 'The Artificial Intelligence Club is for students curious about the real-world applications and impact of AI on our daily lives. Members will explore fundamental concepts, including linear regression and machine learning algorithms, alongside other crucial topics like AI ethics. We’ll offer hands-on experience with a variety of AI tools, from prompt engineering with large language models like ChatGPT to experiment with generative AI through Google’s AI experiments. Exciting guest speakers will come to share their cutting-edge perspectives, and our members will help organize events and workshops to help teach the broader community about Artificial Intelligence. Our goal is to empower members with a deep understanding of AI and its practical day-to-day use, fostering the next generation of AI-literate leaders.', 'STEM & Innovation', 'Tuesday · Weekly · Lunch', 'Room 101', '100034197@mvla.net, 100033313@mvla.net', 'Mr. Alapont', NULL, 0, '[]'),
  (7, 'Asian Pacific Union', 'asian-pacific-union', NULL, 'Asian Pacific Union (APU) aims to foster an environment that promotes the understanding of individual Asian American and Pacific Islander Heritage while still simultaneously creating Unity among students of all ethnic backgrounds. We also ensure that Asian Americans Pacific Islanders as a whole have a voice and community here at Mountain View High school. We appeal to everyone who identifies with Asian Pacific culture and those who want to learn more about Asian Pacific culture.', 'Culture & Identity', 'Tuesday · Biweekly · Lunch', 'Room 210', '100030459@mvla.net', 'Nicole Higley', NULL, 0, '[]'),
  (8, 'Badminton Club', 'badminton-club', NULL, 'Badminton Clubs missions is to provide information for the upcoming season and connect newer players with eachother.', 'Wellness & Athletics', 'Tuesday · Monthly · Lunch', 'Room 103', '100030895@mvla.net', 'Annie Liu', NULL, 0, '[]'),
  (9, 'Barkada Club', 'barkada-club', NULL, 'The Barkada Club aims to strengthen the Mountain View High School community by celebrating and sharing the Filipino culture while making new connections amongst other students. Our primary purpose is to serve as a bridge to bring together Filipino students and allies to share Filipino traditions, foods, and values that can help strengthen our heritage. The club serves as both a home away from home for Filipino students and as an educational platform for other students to learn about and appreciate the Filipino culture.', 'Culture & Identity', 'Wednesday · First and last week of the month · Lunch', 'Room 731', '100030229@mvla.net', 'Mangin', NULL, 0, '[]'),
  (10, 'Biology Club', 'biology-club', NULL, 'The biology club is a place for students to come and learn about the field of biology and all the options it has to offer. From academia to industry we bring in people in the field to talk to students about their path to the job and potential ways. Students can follow that path in today’s society. We also host yearly dissections and pay for the Bio Olympiad, which are the main events that many people involved in biology participate in. We also host reviews for AP students taking biology and places to get tutoring in biology topics.', 'STEM & Innovation', 'Monday · Biweekly · Lunch', 'Room 121', '100030599@mvla.net, 100030696@mvla.net', 'Mr. Cmaylo', NULL, 0, '[]'),
  (11, 'Black Student Union', 'black-student-union', NULL, 'The Black Student Union (BSU) is committed to fostering a safe, empowering, and inclusive space for Black students and allies to celebrate culture, build community, and promote academic and social excellence. Through advocacy, education, and engagement, BSU aims to uplift Black voices, honor heritage, and inspire unity and leadership within our school and beyond.', 'Culture & Identity', 'Thursday · Weekly · Lunch', 'Room 720', '100031136@mvla.net', 'David Ortiz', NULL, 0, '[]'),
  (12, 'Bring Change to Mind Club', 'bring-change-to-mind-club', NULL, 'Bring Change to Mind’s High School Program gives teens a platform to share their voices and raise awareness around mental health. Our goal is to empower students to educate one another, and their communities, and to create a culture of peer support within their schools. Together, we’ll fight the stigma around mental illness. All club members get free access to Headspace to practice mindfulness!', 'Wellness & Athletics', 'Tuesday · Biweekly · Lunch', 'Room 117 or 730', '100030575@mvla.net', 'Latina Wharton and Katie Sheldon', NULL, 0, '[]'),
  (13, 'Cancer Awareness and Research Club', 'cancer-awareness-and-research-club', NULL, 'This organization shall have as its objective and purpose to increase knowledge and awareness about the various types of cancer and their profound impacts on our lives. Through a range of activities and workshops, we aim to educate students on important cancer-related topics. Our club will feature presentations and guest speakers who are experts in the field, providing valuable insights and information. Additionally, we will engage in collaborative group projects to research different aspects of cancer, fostering a deeper understanding among our members. To support the fight against cancer, we will organize fundraising events, with all proceeds going to cancer charities and societies.', 'Service & Leadership', 'Tuesday · Weekly · Lunch', 'Room 121', '100030918@mvla.net, 100030631@mvla.net', 'Mr. Cmaylo', NULL, 0, '[]'),
  (14, 'CASC (California Association of Student Councils) Club', 'casc-california-association-of-student-councils-club', NULL, 'The CASC (California Association of Student Councils) Club aims to educate students around leadership and educational policy/legislation. Our club uses leadership curriculum to teach our students about how they can be leaders and how they can positively impact our community. In addition, our club focuses on educational legislation, creating proposals that often become policies for the California State Board of Education or into laws for the California legislative sector. Our parent organization, CASC, hosts different events supporting educational legislation on a local level and on a state level, many of which we will attend.', 'Service & Leadership', 'Monday · Weekly · Lunch', 'Room 111', '100033627@mvla.net, 100033739@mvla.net', 'Jessica Cohen/Matthew Shih', NULL, 0, '[]'),
  (15, 'Chemistry Club', 'chemistry-club', NULL, 'The Chemistry Club is a group whose members seek a passion in the study of Chemistry, be it in any field (As we plan to go over all sorts), feel like the school’s chemistry classes don’t provide enough depth or interactivity/learning in labs, or are interested in opportunities regarding Chemistry or other related fields that the club will provide, such as guest speakers, projects, and prep for competitions such as Chemistry Olympiad, or internships. We will frequently do interactive activities such as lab demos, so the learning can be applied in an applicable and fun way, something we believe the school should provide more of, with our club as an excellent medium for those interested.', 'STEM & Innovation', 'Tuesday · Weekly · Lunch', 'Room 109', '100030760@mvla.net', 'Mrs. Nock', NULL, 0, '[]'),
  (16, 'Chess Club', 'chess-club', NULL, 'The MVHS Chess Club is dedicated to helping members of the community with varying levels of skill and interest in chess to improve at the game while having fun playing. Chess Club includes teaching lessons to beginners, setting up online/local tournaments, and having in-person boards that members can use. Members can come to the chess club during lunch to play and talk with people who share a common interest in the game.', 'Competition & Strategy', 'Monday · Weekly · Lunch', 'Room 725', '100032003@mvla.net', 'Nathan Bowen', NULL, 0, '[]'),
  (17, 'Children''s Health Advocacy', 'children-s-health-advocacy', NULL, 'Our club’s purpose is to provide comfort and joy to hospitalized children with illnesses. We will create happiness boxes that are for children who are currently in the hospital. These could include seasonal items (like holiday-themed crafts), homemade/club made bracelets, favorite character toys, art supplies, and personalized notes to bring comfort and cheer. We will also volunteer to lead or assist with in-hospital activities like arts and crafts, or game nights designed to distract and entertain children during their hospital stay. Spreading awareness throughout our school and helping our school community understand the importance of empathy and support for children with chronic illnesses is also a major goal of ours.', 'Service & Leadership', 'Tuesday · Biweekly · Lunch', 'Room P8', '100030531@mvla.net, 100031589@mvla.net', 'Mr. Sun', NULL, 0, '[]'),
  (18, 'Chinese Culture Club', 'chinese-culture-club', NULL, 'Mountain View High School''s Chinese Culture Club aims to teach Chinese culture and promote diversity on school grounds. In addition, we plan to create a fun, amiable environment for members to have a good time together while engaging in a variety of Chinese activities such as playing Chinese games, singing Chinese songs, and watching Chinese movies.', 'Culture & Identity', 'Tuesday · Biweekly · Lunch', 'Room 602', '100030920@mvla.net', 'Wei Lu', NULL, 0, '[]'),
  (19, 'Computer Science Club', 'computer-science-club', NULL, 'The Computer Science Club aims to provide a space for students of all coding backgrounds to explore computer science. We offer engaging, student-led lessons, collaborative projects, and community events to help members develop programming skills. Our goal is to provide a space for students interested in tech to learn together and engage with like-minded peers in programming projects that address a need or concern in the community.', 'STEM & Innovation', 'Thursday · Weekly · Lunch', 'Room 806', '100030743@mvla.net', 'Ly Nguyen', NULL, 0, '[]'),
  (20, 'Connected Through Cultures', 'connected-through-cultures', NULL, 'The purpose of Connected Through Cultures is to raise awareness about diverse cultures and provide a space for students whose cultural identities are not encompassed by already-existing student unions, filling a vital gap in our school community. We aim to foster an inclusive environment for students from diverse cultural backgrounds, particularly those without dedicated representation, to come together and share their unique traditions, stories, and perspectives. Our club is open to everyone, offering a variety of multicultural activities such as folk dances, educational lectures, and traditional games, with the overall goal of promoting a sense of unity that extends past connections between people of the same culture.', 'Culture & Identity', 'Thursday · Biweekly · Lunch', 'Room 729', '100030798@mvla.net', 'Julie Yick', NULL, 0, '[]'),
  (21, 'Crochet Club', 'crochet-club', NULL, 'The Crochet Club is a welcoming community where all those interested in crocheting can come and learn (including beginners)! We will provide free yarn, hooks, darning needles, and other related materials so all club members can learn at no expense to themselves. The Crochet Club will facilitate donation events to allow students who are interested in giving back to the community to do so (e.g. warm items such as beanies and scarves) and will also host semesterly volunteer events with local organizations to work with and bring a fun experience to residents. We will also teach specific fun projects to increase our club members’ interest in crocheting (e.g. flowers, bookmarks, and amigurumi).', 'Creative Arts & Media', 'Thursday · Biweekly · Lunch', 'Room 109', '100030741@mvla.net', 'Lori Nock', NULL, 0, '[]'),
  (22, 'Dance-a-Gram', 'dance-a-gram', NULL, 'Dance-a-Gram aims to spread joy and form a deeper connection with the senior community through coordinated dance performances. For seniors, watching dance can be a great way to relax, to bring back memories, and to spark conversation. The dance performances we conduct can brighten up their day and can even expose them to art forms and cultures that they’ve never interacted with before.', 'Creative Arts & Media', 'Thursday · Weekly · Lunch', 'Room 607', '100033205@mvla.net', 'Lauren Camarillo', NULL, 0, '[]'),
  (23, 'DERM (Dermatology Educational Research Mission) Club', 'derm-dermatology-educational-research-mission-club', NULL, 'The Dermatology Education Research Mission (DERM) club seeks to educate Mountain View High School students about the integumentary system, raise awareness of skin health, and inspire curiosity in dermatology through education, hands-on activities, and community engagement.', 'STEM & Innovation', 'Thursday · Biweekly · Lunch', 'Room 117', '100031861@mvla.net', 'Jenna Adams', NULL, 0, '[]'),
  (24, 'Drama Llamas', 'drama-llamas', NULL, 'Drama Llamas is an entirely student-run club that puts on a full-scale musical at the end of each school year. The show is directed, teched, choreographed, managed, produced, performed, and sometimes even written by students of Mountain View High School. We were founded with the intent of making all aspects of theatre available to everyone, regardless of past experience. We are committed to creating student-run theater and learning leadership skills.', 'Creative Arts & Media', 'Weekly · After School', 'Room 125', '100031107@mvla.net', 'Anthony Gallego', NULL, 0, '[]'),
  (25, 'Dream Volunteers', 'dream-volunteers', NULL, 'The dream volunteers club is a club for people who want a way to give back to their community. It is based on the organization Dream Volunteers, who organize service trips to other countries. Our member do not have to go on any trips, but they will learn about and particiapte in outside of school volunteer oppurtunies dicsovered by us.', 'Service & Leadership', 'Monday · Biweekly · Lunch', 'Room 604', '100033849@mvla.net', 'Ms. Stucker', NULL, 0, '[]'),
  (26, 'MVHS Drivers Association', 'mvhs-drivers-association', NULL, 'The MVHS Driver’s Association seeks to eradicate the confusion around the process of acquiring a drivers license that prevents many from doing so. By spreading information and resources on how to get a drivers license, we provide students with opportunities to learn where, how, and when to get one. We also teach car maintenance skills and basics, and help students prepare for their permit and license tests. We are open to all, regardless of driving experience, who want to learn, teach, or just have fun.', 'Service & Leadership', 'Wednesday · Biweekly · Lunch', 'Room 115', '100031957@mvla.net', 'Simon Huynh', NULL, 0, '[]'),
  (28, 'Economics Club', 'economics-club', NULL, 'The Economics Club is a community of students curious about how societies allocate resources and make choices. We emphasize the broader study of economic systems, policies, and theories (from supply and demand to global trade). Through case studies, and debates on current events, members can learn to think critically about how economic forces shape the world. Our goal is to build a foundation in both microeconomics and macroeconomics while connecting theory to real-world issues. In addition, we participate in the National Economics Challenge, where students apply their knowledge of core principles and analytical reasoning in a competitive setting.', 'Service & Leadership', 'Friday · Biweekly · Lunch', 'Room 609', '100032162@mvla.net', 'Rachael Roach', NULL, 0, '[]'),
  (29, 'Esports Club', 'esports-club', NULL, 'The purpose of Mountain View Esports is to promote the growth of esports at Mountain View School by providing students with opportunities to engage in competitive gaming, develop skills in teamwork and strategy, and participate in local and national esports competitions. The club also aims to foster a positive gaming culture and build a supportive community among students', 'Competition & Strategy', 'Friday · Biweekly · Lunch', 'Room 115', '100030745@mvla.net', 'Mr Simon', NULL, 0, '[]'),
  (30, 'F=ma Club', 'f-ma-club', NULL, 'The F=ma club is a group whose members are focused on studying for the F=ma exam, which is taken in February, in hopes of qualifying for USAPhO. Our members work together during meetings to learn new concepts and solve problems together to improve their test-taking and problem solving skills.', 'Competition & Strategy', 'Tuesday · Weekly · Lunch', 'Room 617', '100030715@mvla.net', 'Mr. West', NULL, 0, '[]'),
  (31, 'Fellowship of Christian Athletes', 'fellowship-of-christian-athletes', NULL, 'The vision of FCA is to see the world transformed by Jesus Christ through the influence of coaches and athletes.', 'Service & Leadership', 'Tuesday · Monthly · Lunch', 'Room P6', '100030417@mvla.net', 'Tim Lugo', NULL, 0, '[]'),
  (32, 'Fentanyl & Substance Awareness Club', 'fentanyl-substance-awareness-club', NULL, 'The Fentanyl & Substance Awareness Club has a long term goal of helping to protect MVHS students and our broader community from drug overdoses, particularly those relating to fentanyl. During our bi-weekly meetings, we hope to gather passionate student leaders and work together to improve our personal understanding of the fentanyl crisis and pre-existing policies that work to address it. From there, we hope to share our knowledge with other MVHS students as well as local middle schoolers.', 'Service & Leadership', 'Monday · Biweekly · Lunch', 'Room 116', '100030863@mvla.net, 100032144@mvla.net', 'Mr. Panos', NULL, 0, '[]'),
  (33, 'Film Club', 'film-club', NULL, 'The Film Club welcomes both film enthusiasts and newcomers into engaging discussions regarding all genres of film! Every week, we recommend films to each other and pick movies to watch as a club, which we later review and discuss together. Our goal is to not only discuss what parts of the film we liked, but also take note of the artistic and mechanical aspects of the film. Making the art of cinema and filmmaking available to everyone on campus. Club members also have the opportunity to share their interests through optional film presentations. If you have a favorite film you can’t stop watching, Film Club is the perfect opportunity to share that passion.', 'Creative Arts & Media', 'Friday · Weekly · Lunch', 'Room 103', '100030312@mvla.net', 'Ms. Liu', NULL, 0, '[]'),
  (34, 'Foreign Linguistics Club', 'foreign-linguistics-club', NULL, 'The Linguistics Club aims to create a space where students can explore the scientific study of language in an engaging and accessible way. Through presentations, activities, and outreach, we encourage curiosity about how language works, its role in society, and its connection to culture and identity. Our mission is to make linguistics approachable and relevant to students of all backgrounds and interests.', 'Service & Leadership', 'Monday · Weekly · Lunch', 'Room P3', '100030716@mvla.net', 'Ms. Wu', NULL, 0, '[]'),
  (35, 'French Club', 'french-club', NULL, 'The mission of the French Club is to celebrate the uniqueness and beauty of French culture and traditions and spread it to our surrounding community, in a way that is accommodating of all. This is done through the celebration of French holidays, the honoring of French art, and the playing of French games.', 'Service & Leadership', 'Friday · Biweekly', 'Room 603', 'maggie.h.zhang@gmail.com', 'Clotilde Grès', NULL, 0, '[]'),
  (38, 'Gender Sexuality Alliance', 'gender-sexuality-alliance', NULL, 'The Gender-Sexuality Alliance Club is a group seeking to develop a safe space on campus, from those questioning their sexuality or gender to openly out students looking to find like minds to ensure their identities are respected. By encouraging LGBTQ+ students to form powerful group connections and hosting awareness events around campus, such as organizing conferences on how to handle coming out or through a gender-affirming clothes drive, we hope to lessen the disproportionate mental-health burden queer students face.', 'Service & Leadership', 'Friday · Weekly · Lunch', 'Room 726', '100030774@mvla.net', 'Felitia Hancock', NULL, 0, '[]'),
  (39, 'Girls Who Code Club', 'girls-who-code-club', NULL, 'The Girls Who Code Club works to foster an environment in which women in technology at MVHS feel welcome and comfortable to develop their coding skills and to teach members of the community more about computer science through lessons in coding and attending fun events like hackathons. We work towards small-scale individual projects and group projects where club members develop their own websites and teach code at local middle schools.', 'Service & Leadership', 'Monday · Weekly · Lunch', 'Room 801', '100030691@mvla.net', 'Mrs. Winawer', NULL, 0, '[]'),
  (40, 'Guitar Culture Club', 'guitar-culture-club', NULL, 'The Guitar Culture Club (GCC) unites musicians and music lovers to explore the art, history, and culture of the guitar. We serve the Mountain View community by hosting performances, sharing musical knowledge, and creating inclusive spaces where people of all skill levels can connect, learn, and celebrate music together.', 'Service & Leadership', 'Friday · Weekly · Lunch', 'Room 121', '100030857@mvla.net', 'David Cmaylo', NULL, 0, '[]'),
  (41, 'Ignition Club', 'ignition-club', NULL, 'Our mission is to provide technology education accessible to all levels of students and inform them of the transformations in technology in our modern world.', 'Service & Leadership', 'Wednesday · Biweekly · Lunch', 'Room 123', '100030858@mvla.net, 100030761@mvla.net', 'Ann Nguyen', NULL, 0, '[]'),
  (42, 'INARA', 'inara', NULL, 'The INARA Club fundraises for INARA, an organization that provides medical aid to refugee children in war torn countries. Students participate in fundraisers and activities, host interviews with field professionals, and learn about INARA case studies and current humanitarian, political, socioeconomic, and health related issues in the Middle East. Members can expect to hone skills like networking, entrepreneurship, and activism.', 'Service & Leadership', 'Wednesday · Biweekly · Lunch', 'Room 729', '100030812@mvla.net, 100030777@mvla.net', 'Julie Yick', NULL, 0, '[]'),
  (43, 'Information Security Club', 'information-security-club', NULL, 'The Information Security Club is dedicated to educating students about various aspects of offensive and defensive information security. To give back to the community, some community projects that the club participates in include contributing code to make free and open source software, and contributing writeups/tutorials online to assist beginning information security students.', 'STEM & Innovation', 'Tuesday · Weekly · Lunch', 'Room 513', '100032056@mvla.net, 100031313@mvla.net', 'Ms. Chiu', NULL, 0, '[]'),
  (44, 'Japanese Culture Club', 'japanese-culture-club', NULL, 'Japanese Culture Club is a group whose members are interested in a more in-depth study of Japanese culture, including music, Anime, video games, Cosplay, Food, Origami, Ping-pong, and so on. Japan Club is where students learn or share Japanese cultural activities.', 'Service & Leadership', 'Thursday · Weekly · Lunch', 'Room 601', '100030227@mvla.net', 'Minako Walther', NULL, 0, '[]'),
  (45, 'Japanese National Honor Society', 'japanese-national-honor-society', NULL, 'This organization shall have as its objective and purpose to spread Japanese History and Tradition at MVHS through Japanese-related presentations and traditional activities. Any student enrolled in Mountain View High School who has completed or enrolled in 2 years of Japanese Courses, maintaining a 3.5 GPA while also maintaining an overall 3.0 GPA in all MVHS courses, shall be eligible members of the Japanese National Honor Society.', 'Service & Leadership', 'Wednesday · Monthly · Lunch', 'Room 601', '100030227@mvla.net', 'Minako Walther', NULL, 0, '[]'),
